pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Warp to a deterministic block so random == 0
        vm.warp(1);
        vm.roll(1);

        // First player: alice wins (random == 0)
        vm.deal(address(0x1), 10);
        vm.prank(address(0x1));
        c.play{value: 10}();

        // Second player: bob plays and wins
        vm.deal(address(0x2), 10);
        vm.prank(address(0x2));
        c.play{value: 10}();

        // Reference: after first win pot reset to 0, after second win pot becomes 0 + 10 - 1 = 9 then reset to 0
        // Mutant: after first win pot stays 10, after second win pot becomes 10 + 10 - 1 = 19 NOT reset
        // So reference has pot == 0, mutant has pot == 19
        assertTrue(c.pot() == 0);
    }
}

