    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Give the player 10 wei
        address player = address(0x123);
        vm.deal(player, 10);

        // Player plays
        vm.prank(player);
        c.play{value: 10}();

        // After play(), if random == 0, the reference would have transferred pot-1=9 to player
        // but the mutant (pot-=10) would have pot=0 and transfer 0-1 underflows -> revert
        // So we check that pot is 10 in reference and 0 in mutant
        // But the divergence is directly observable: pot is 10 in reference, 0 in mutant
        // We need to detect the bug after the transaction: the mutant's pot will be 0
        // To ensure we capture the scenario where random==0 (and the reference transfers), 
        // we warp to a fixed timestamp that yields random=0
        vm.warp(1);
        vm.difficulty(1);
        // Reset state: deploy new contract and replay with deterministic randomness
        c = new C();
        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        // Reference: pot == 10 (since pot += 10, then if random==0, pot set to 0, but after the if, pot = 0)
        // Wait, actually in reference: pot += 10 -> pot = 10, then if random==0: transfer 1 to bank, transfer 9 to player, pot = 0
        // In mutant: pot -= 10 -> pot = -10 (underflow revert if using unchecked, but Solidity 0.8 reverts on underflow)
        // So actually the mutant reverts before the if! This is even more clear.
        // So we assert that in the reference, the call succeeds and pot becomes 0,
        // while in the mutant the call reverts. We test this with try/catch.

        // Actually let's simplify: we just check that after a successful play (reference), pot is 0;
        // in the mutant, the call will revert due to underflow.
        // So we use try/catch to catch the revert.
        bool ok;
        c = new C();
        vm.deal(player, 10);
        vm.prank(player);
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, play succeeds (random may be 0 or 1, but either way no underflow)
        // In the mutant, pot -= 10 causes an underflow revert (pot initialized to 0, 0-10 underflows)
        // So assertTrue(ok) holds for reference, fails for mutant
        assertTrue(ok);
    }
}

